pix": 408.41, "parcelamento": "6x de R$ 71,65 Sem juros", "imagens": [{"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_nautico_reebok_2026_uniforme_1_jogador_masculino_3345_1_6c77ba32f41bf3283001ea3c5342fca2.jpg", "tipo": "frente"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_nautico_reebok_2026_uniforme_1_jogador_masculino_3345_2_7e833617896854a842d9cfc0a633049d.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_nautico_reebok_2026_uniforme_1_jogador_masculino_3345_3_80a5fd8e9bb7b965ef762c1781d51fa1.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_nautico_reebok_2026_uniforme_1_jogador_masculino_3345_4_3ba5483807a49c5590811a10167f9e0c.jpg", "tipo": "extra"}], "video_url": "https://www.youtube.com/embed/YoGEMm3zJPQ", "propriedades": {"Categoria": ["Camisa"], "Clubes": ["Náutico"], "Gênero": ["Masculino"]}, "lancamento": false, "destaque": false, "coletado_em": "2026-11-24T20:16:44.930870+00:00"}, {"item_group_id": "OLD-P3347", "id_loja": "3347", "nome": "Camisa Fluminense Puma 2026 Uniforme 2 Torcedor - Masculino", "slug": "clubes/camisa-fluminense-puma-2026-uniforme-2-torcedor-masculino", "url": "https://www.oldensports.com.br/clubes/camisa-fluminense-puma-2026-uniforme-2-torcedor-masculino", "marca": "Puma", "categoria": "Camisa", "departamento": "camisas", "clube": "Fluminense", "genero": "masculino", "faixa_etaria": "adulto", "descricao": "Camisa Fluminense Puma 2026 Uniforme 2 Torcedor - Masculino\nMais do que um uniforme, esta camisa representa um verdadeiro manto sagrado. Criada para proteger, inspirar e impulsionar jogadores e torcedores, ela traduz a fé inabalável de quem carrega o Tricolor no coração.\nCada detalhe exalta a identidade e a tradição do clube, mostrando que esse sentimento vai muito além da paixão: é amor, orgulho e devoção.\nCARACTERÍSTICAS E BENEFÍCIOS\nTecnologia dryCELL: sistema de alta performance desenvolvido para absorver a umidade do corpo e facilitar sua evaporação, mantendo a pele seca e confortável por mais tempo.\nTecido Mesh: estrutura leve e respirável que favorece a circulação de ar e proporciona maior conforto durante o uso.\nDETALHES\n- Modelagem regular\n- Gola careca com recorte\n- Detalhe tricolor na gola\n- Arte em relevo embossing na parte frontal\n- Logo PUMA bordado no lado direito do peito\n- Escudo oficial do clube bordado no lado esquerdo do peito\n- Frase ?Amor igual não se viu? aplicada nas costas\n- Logos PUMA aplicados nos ombros\nCOMPOSIÇÃO\nMaterial 100% poliéster\nMedidas Aproximadas A X L:\nP (S): 69 x 48 cm\nM (M): 71 x 52 cm\nG (L): 73 x 56 cm\nGG (XL): 78 x 60 cm\nXG (XXL): 79 x 68 cm", "medidas": "Medidas Aproximadas A X L:\nP (S): 69 x 48 cm\nM (M): 71 x 52 cm\nG (L): 73 x 56 cm\nGG (XL): 78 x 60 cm\nXG (XXL): 79 x 68 cm", "preco": 429.9, "preco_promocional": 213.9, "preco_pix": 203.21, "parcelamento": "6x de R$ 35,65 Sem juros", "imagens": [{"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_fluminense_puma_2026_uniforme_2_torcedor_masculino_3347_1_5f723c7cf5567b2851fb34eb5293dec8.jpg", "tipo": "frente"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_fluminense_puma_2026_uniforme_2_torcedor_masculino_3347_2_2dcc587c5edcd70d32a52a58f8459a0c.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_fluminense_puma_2026_uniforme_2_torcedor_masculino_3347_3_e6c6f16ac403e8996b896502db426c7d.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_fluminense_puma_2026_uniforme_2_torcedor_masculino_3347_4_40a3ca2ee1ad4d9df7438aa02f362254.jpg", "tipo": "extra"}], "video_url": "https://www.youtube.com/embed/j9UlLEBZxko", "propriedades": {"Categoria": ["Camisa"], "Clubes": ["Fluminense"], "Gênero": ["Masculino"]}, "lancamento": false, "destaque": false, "coletado_em": "2026-11-24T20:16:44.930870+00:00"}, {"item_group_id": "OLD-P3359", "id_loja": "3359", "nome": "Camisa Atlético Mineiro Eder 1983 Retrômania - Masculino", "slug": "clubes/camisa-atletico-mineiro-eder-1983-retromania-masculino", "url": "https://www.oldensports.com.br/clubes/camisa-atletico-mineiro-eder-1983-retromania-masculino", "marca": "Retrômania", "categoria": "Camisa", "departamento": "camisas", "clube": "Atlético Mineiro", "genero": "masculino", "faixa_etaria": "adulto", "descricao": "Camisa Retrô Atlético Mineiro 1983 Eder Oficial\nCamisa Retro com a assinatura do grande ídolo Eder homenageando o hexa mineiro no ano de 1983.\nProduzido em 100% algodão extremamente confortável e macio, esse manto é perfeito para o torcedor raiz que quer vestir as cores do time no dia a dia.\n- Tecido 100% algodão de alta qualidade\n- Escudo bordado em alta definição\n- Produto oficial licenciado Atlético Mineiro\nDimensões Aproximadas (A x L):\nP: 67 x 49 cm\nM: 69 x 51 cm\nG: 71 x 53 cm\nGG: 73 x 55 cm\nEG: 75 x 57 cm", "medidas": null, "preco": 229.9, "preco_promocional": 209.9, "preco_pix": 199.41, "parcelamento": "6x de R$ 34,98 Sem juros", "imagens": [{"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_atletico_mineiro_eder_1983_retromania_masculino_3359_1_3f44953062002c69a637f89f4f8b4576.jpg", "tipo": "frente"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_atletico_mineiro_eder_1983_retromania_masculino_3359_2_a586e41e808d5c8341d576bd8d0db719.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_atletico_mineiro_eder_1983_retromania_masculino_3359_3_d6f17aa2bac7f2045116e6ce0206d063.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_atletico_mineiro_eder_1983_retromania_masculino_3359_4_414741ef5eecc4364c88e7ac311c1edb.jpg", "tipo": "extra"}], "video_url": null, "propriedades": {"Categoria": ["Camisa"], "Clubes": ["Atlético Mineiro"], "Gênero": ["Masculino"]}, "lancamento": false, "destaque": false, "coletado_em": "2026-11-24T20:16:44.930870+00:00"}]$dados$::jsonb) as x(item_group_id text, id_loja text, nome text, slug text, url text, marca text, categoria text, departamento text, clube text, genero text, faixa_etaria text, descricao text, medidas text, preco numeric, preco_promocional numeric, preco_pix numeric, parcelamento text, imagens jsonb, video_url text, propriedades jsonb, lancamento boolean, destaque boolean, coletado_em timestamptz)
on conflict (item_group_id) do update set id_loja = excluded.id_loja, nome = excluded.nome, slug = excluded.slug, url = excluded.url, marca = excluded.marca, categoria = excluded.categoria, departamento = excluded.departamento, clube = excluded.clube, genero = excluded.genero, faixa_etaria = excluded.faixa_etaria, descricao = excluded.descricao, medidas = excluded.medidas, preco = excluded.preco, preco_promocional = excluded.preco_promocional, preco_pix = excluded.preco_pix, parcelamento = excluded.parcelamento, imagens = excluded.imagens, video_url = excluded.video_url, propriedades = excluded.propriedades, lancamento = excluded.lancamento, destaque = excluded.destaque, coletado_em = excluded.coletado_em, ativo = true;

